Definition AEXIT_W1 (sp : Z) : list (Z * Z) :=
  [(sp - 48 - MDTOR_DEPTH, sp); (0x60d500, 0x60d504); (0x60d2e0, 0x60d2e1); (0x60d2e8, 0x60d2ec); (0x60d2f0, 0x60d2f8); (0xb6c90, 0xb6c91)]%Z.
Definition AEXIT_W (sp : Z) : list (Z * Z) := AEXIT_W1 sp ++ MDTOR_W.

(* [comment removed for export] *)
Definition aexit_prefix_post (sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo code t : Z) (ra : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 0xa1cb0) (Z_to_bv 64 (bv_unsigned sp + -16)) gp (Z_to_bv 64 RTP) t0 t1 t2 (Z_to_bv 64 code) s1
                 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xa7734) fc None m' (seg_rom bsegs)
    /\ munch [(bv_unsigned sp - 48 - 1024, bv_unsigned sp); (0x60d500, 0x60d504); (0x60d2e0, 0x60d2e1); (0x60d2e8, 0x60d2ec);
              (0x60d2f0, 0x60d2f8); (0xb6c90, 0xb6c91);
              (0xb6c40, 0xb6c48); (0xb7bb0, 0xb7bb8); (0x7fffc1c0, 0x7fffc250); (0x8000ed3e, 0x8000ed86)]%Z m m'
                                                                  (* [comment removed for export] *)
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -16)
    /\ rw_cells bsegs m' (bv_unsigned sp + -16) [C8 s0; C8 ra]
    /\ rw_cells bsegs m' 0x5ed1e8 [C4 (Z_to_bv 64 t)]
    /\ rw_cells bsegs m' 0x60d500 [C4 (Z_to_bv 64 t)]
    /\ rw_cells bsegs m' 0xb6c90 [C1 (Z_to_bv 8 1)].

Section Prefix.
  Variable PRE : mem -> Prop.
  Hypothesis MDTOR : module_dtor_stmt PRE.
  (* [comment removed for export] *)
  Hypothesis PRE_frame : forall sp m m', PRE m -> (KHIGH <= sp - 48 - MDTOR_DEPTH)%Z -> munch (AEXIT_W1 sp) m m' -> wmono bsegs m m' -> PRE m'.

  Lemma aexit_prefix_spec : forall (reg : bool) RNG ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (lo : Z) (code t : Z) (cdt thr sec : byte) (tm1 dso : word),
    PRE m ->
    stk bsegs m lo (bv_unsigned sp) ->
    rw_cells bsegs m 0x5ed1e8 [C4 (Z_to_bv 64 t)] ->                                   (* [comment removed for export] *)
    rw_cells bsegs m 0x60d500 [C4 z64] ->                                             (* [comment removed for export] *)
    rw_cells bsegs m 0x60d520 [C1 cdt; C1 thr; C1 sec; C1 (Z_to_bv 8 0); C4 tm1] ->       (* [comment removed for export] *)
    atx_stateA reg m ->                                                               (* [comment removed for export] *)
    rw_cells bsegs m 0xb2e00 [C8 (Z_to_bv 64 0xb1bc0); C8 (Z_to_bv 64 0xb1bb0)] -> (* [comment removed for export] *)
    rw_cells bsegs m 0xb1bb0 [C8 (Z_to_bv 64 0x969cc); C8 (Z_to_bv 64 0x3072c)] ->  (* [comment removed for export] *)
    rw_cells bsegs m 0xb6c90 [C1 (Z_to_bv 8 0)] ->                                   (* [comment removed for export] *)
    rw_cells bsegs m 0xb20f8 [C8 (Z_to_bv 64 0xa1b28); C8 z64] ->                   (* [comment removed for export] *)
    rw_cells bsegs m 0xb3e40 [C8 dso] ->                                             (* [comment removed for export] *)
    mem_inv bsegs m ->
    tp = Z_to_bv 64 RTP -> a0 = Z_to_bv 64 code ->
    (0 < t < 4194304)%Z -> (lo <= bv_unsigned sp - 48 - MDTOR_DEPTH)%Z -> (KHIGH <= lo)%Z ->
    rng RNG lo (bv_unsigned sp - lo) -> rng_aimg RNG -> Forall (fun iv => rng RNG (fst iv) (snd iv - fst iv)) MDTOR_W ->
    evtF bsegs RNG (aexit_prefix_post sp gp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc lo code t ra m)
        (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
